BEGIN TRANSACTION;
CREATE TABLE "code_sessions" (session_id VARCHAR NOT NULL, session_type VARCHAR NOT NULL, agent_id VARCHAR, team_id VARCHAR, workflow_id VARCHAR, user_id VARCHAR, session_data JSON, agent_data JSON, team_data JSON, workflow_data JSON, metadata JSON, summary JSON, created_at BIGINT NOT NULL, updated_at BIGINT, PRIMARY KEY (session_id));
INSERT INTO "code_sessions" VALUES('session','team',NULL,'squad',NULL,NULL,'{"session_state": {}}',NULL,NULL,NULL,'null',NULL,1750000000,1750000000);
CREATE TABLE "code_sessions_removed_runs" (run_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES "code_sessions"(session_id) ON DELETE CASCADE);
CREATE TABLE "code_sessions_runs" (run_id VARCHAR NOT NULL, session_id VARCHAR NOT NULL, run_type VARCHAR NOT NULL, agent_id VARCHAR, team_id VARCHAR, workflow_id VARCHAR, user_id VARCHAR, parent_run_id VARCHAR, status VARCHAR, run_index BIGINT, run_data JSON NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT, PRIMARY KEY (run_id), FOREIGN KEY(session_id) REFERENCES "code_sessions" (session_id) ON DELETE CASCADE);
